<div class="table-wrap"><table><thead><tr><th>No. Permohonan</th><th>Pemohon</th><th>Barang</th><th>Jenis</th><th>Jadwal</th><th>Status</th><?php if($isStaff??false):?><th>Aksi</th><?php endif?></tr></thead><tbody><?php foreach($q as $l):?><tr><td><strong><?=e($l['loan_no'])?></strong><small><?=date('d M Y',strtotime($l['created_at']))?></small></td><td><?=e($l['borrower'])?></td><td><strong><?=e($l['name'])?></strong><small><?=e($l['asset_code']??'')?></small></td><td><span class="pill <?=$l['loan_type']==='jangka_panjang'?'purple':'blue'?>"><?=e(status_label($l['loan_type']))?></span></td><td><?=date('d M Y',strtotime($l['start_date']))?><small>s.d. <?=date('d M Y',strtotime($l['due_date']))?></small></td><td><span class="pill <?=e($l['status'])?>"><?=e(status_label($l['status']))?></span></td><?php if($isStaff??false):?><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$l['id']?>"><input type="hidden" name="back" value="<?=e($page)?>"><input type="hidden" name="loan_type" value="<?=e($loanType??$l['loan_type'])?>"><?php if($l['status']==='menunggu'):?><button name="action" value="approve" class="approve">Setujui</button><button name="action" value="reject" class="reject" onclick="return confirm('Tolak permohonan ini?')">Tolak</button><?php elseif($l['status']==='disetujui'):?><button name="action" value="checkout" class="approve">Serahkan</button><?php elseif(in_array($l['status'],['dipinjam','terlambat'])):?><button name="action" value="return" class="approve" onclick="return confirm('Konfirmasi barang telah kembali?')">Terima</button><?php else:?><span class="muted">Selesai</span><?php endif?></form></td><?php endif?></tr><?php endforeach?></tbody></table></div>
